        value = row[field]
        if not isinstance(condition, dict):
            condition = {'eq': condition}
        for op, target in condition.items():
            if op == 'eq': ok = value == target
            elif op == 'in': ok = value in target if not isinstance(value, list) else any(v in value for v in target)
            elif op == 'contains': ok = target.lower() in value.lower() if isinstance(value, str) and isinstance(target, str) else target in value if isinstance(value, list) else False
