from pathlib import Path
import csv

def run(arguments, context):
    root = context.scope_root('business_data').resolve()
    def inside(ref):
        path = (root / ref).resolve()
        if not path.is_relative_to(root):
            return None
        return path
    def metadata(path):
        with path.open('r', encoding='utf-8-sig', newline='') as stream:
            first = stream.readline().rstrip('\r\n')
        fmt = 'csv' if path.suffix.lower() == '.csv' else 'source_text'
        width = len(next(csv.reader([first]))) if fmt == 'csv' else len(first.split())
        return {'file_ref':path.relative_to(root).as_posix(),'size_bytes':path.stat().st_size,
                'format':fmt,'first_line':first,'column_count':width}
    if 'file_ref' in arguments:
        path = inside(arguments['file_ref'])
        if path is None or not path.is_file():
            return {'success':False,'error':{'code':'not_found','path':'file_ref','message':'文件不存在','retryable':False}}
        return {'success':True,'data':{'files':[metadata(path)],'total':1}}
    directory = inside(arguments.get('directory_ref','.'))
    if directory is None or not directory.is_dir():
        return {'success':False,'error':{'code':'not_found','path':'directory_ref','message':'目录不存在','retryable':False}}
    files = [metadata(path) for path in sorted(directory.rglob('*')) if path.is_file() and path.resolve().is_relative_to(root)]
    return {'success':True,'data':{'files':files,'total':len(files)}}

