from datetime import datetime

HEADERS = {'st_awfd/D1.csv': ['MaterialID', 'StepID', 'duration_ms', 'feature_1', 'feature_2', 'feature_3', 'feature_4', 'feature_5', 'feature_6', 'feature_7', 'feature_8', 'feature_9', 'feature_10', 'feature_11', 'feature_12', 'feature_13', 'feature_14', 'feature_15', 'is_test', 'target'], 'st_awfd/D2.csv': ['MaterialID', 'StepID', 'duration_ms', 'feature_1', 'feature_2', 'feature_3', 'feature_4', 'feature_5', 'feature_6', 'feature_7', 'feature_8', 'feature_9', 'feature_10', 'feature_11', 'feature_12', 'feature_13', 'feature_14', 'feature_15', 'feature_16', 'feature_17', 'feature_18', 'feature_19', 'feature_20', 'is_test', 'target'], 'secom_wafer_analytics/fdc_monitoring_scores.csv': ['t2', 'spe', 't2_alarm', 'spe_alarm', 'any_alarm'], 'secom_wafer_analytics/alarm_catalog.csv': ['wafer_idx', 'timestamp', 't2', 'spe', 't2_norm', 'spe_norm', 'alarm_type', 'is_fail', 'top_t2_sensors', 'top_t2_values', 'top_spe_sensors', 'top_spe_values', 'severity'], 'secom_wafer_analytics/fdc_methodology_comparison.csv': ['', 'K', 'var_explained', 'T2_limit', 'SPE_limit', 'TP', 'FP', 'FN', 'TN', 'TPR', 'FPR', 'Precision', 'F1'], 'secom_wafer_analytics/spc_summary.csv': ['sensor', 'mu', 'mu_monitoring', 'mean_shift_sigma', 'sigma_within', 'sigma_overall', 'drift_ratio', 'Cp', 'Cpk_baseline', 'Cpk_monitoring', 'flagged_points', 'n_monitoring', 'flag_rate', 'rule_1', 'rule_2', 'rule_3', 'rule_4', 'rule_5', 'rule_6', 'rule_7', 'rule_8']}
EXPECTED_COUNTS = {'st_awfd/D1.csv': 602108, 'st_awfd/D2.csv': 126794, 'secom_wafer_analytics/fdc_monitoring_scores.csv': 543, 'secom_wafer_analytics/alarm_catalog.csv': 39, 'secom_wafer_analytics/fdc_methodology_comparison.csv': 2, 'secom_wafer_analytics/spc_summary.csv': 25, 'secom_wafer_analytics/secom.data': 1567, 'secom_wafer_analytics/secom_labels.data': 1567}

def run(arguments, context):
    ref = arguments['file_ref']
    root = context.scope_root('business_data').resolve()
    path = (root / ref).resolve()
    if not path.is_relative_to(root) or not path.is_file():
        return {'success':False,'error':{'code':'not_found','path':'file_ref','message':'文件不存在','retryable':False}}
    if ref not in EXPECTED_COUNTS:
        return {'success':False,'error':{'code':'unsupported_format','path':'file_ref','message':'没有该业务文件的格式声明','retryable':False}}
    errors = []
    error_count = 0
    def issue(row,column,code,message):
        nonlocal error_count
        error_count += 1
        if len(errors) < 30:
            errors.append({'row':row,'column':column,'code':code,'message':message})
    def number(value, allow_nan=False):
        n = float(value)
        if not math.isfinite(n) and not (allow_nan and math.isnan(n)):
            raise ValueError('非有限数值')
    is_csv = path.suffix.lower() == '.csv'
    fmt = 'csv' if is_csv else 'source_text'
    header = None
    count = 0
    width = 0
    if is_csv:
        expected = HEADERS[ref]
        with path.open('r',encoding='utf-8-sig',newline='') as stream:
            reader = csv.reader(stream,strict=True)
            try:
                header = next(reader)
                width = len(header)
                if header != expected: issue(1,'*','header','表头与业务文件定义不一致')
                for row in reader:
                    count += 1
                    line = reader.line_num
                    if len(row) != len(expected):
                        issue(line,'*','row_width','行宽与表头不一致')
                        continue
                    for col,value in zip(expected,row):
                        if value.strip() == '':
                            issue(line,col or 'index','missing_value','关键字段为空')
                            continue
                        try:
                            if col in ('MaterialID','StepID','wafer_idx','flagged_points','n_monitoring') or col.startswith('rule_'):
                                int(value)
                            elif col in ('is_test','target','t2_alarm','spe_alarm','any_alarm','is_fail'):
                                if value not in ('True','False','0','1'): raise ValueError('布尔值无效')
                            elif col == 'timestamp':
                                datetime.fromisoformat(value)
                            elif col in ('alarm_type',):
                                if value not in ('T2-only','SPE-only','both'): raise ValueError('告警类别无效')
                            elif col == 'sensor' or col == '' or col == 'top_t2_sensors' or col == 'top_spe_sensors':
                                if col.startswith('top_') and not all(value.split(';')): raise ValueError('传感器列表无效')
                            elif col in ('top_t2_values','top_spe_values'):
                                for part in value.split(';'): number(part)
                            else: number(value)
                        except ValueError:
                            issue(line,col or 'index','field_type','字段类型或取值无效')
            except (csv.Error, StopIteration) as exc:
                issue(1,'*','csv_parse','CSV 解析失败或缺少表头')
    else:
        width = 590 if ref.endswith('/secom.data') else 2
        with path.open('r',encoding='utf-8-sig') as stream:
            for line_num,line in enumerate(stream,1):
                count += 1
                try:
                    parts = line.split() if width == 590 else shlex.split(line)
                except ValueError:
                    issue(line_num,'*','row_parse','源文本行解析失败')
                    continue
                if len(parts) != width:
                    issue(line_num,'*','row_width','源文本列数不符')
                    continue
                for pos,value in enumerate(parts,1):
                    try:
                        if width == 590: number(value,allow_nan=True)
                        elif pos == 1:
                            if int(value) not in (-1,1): raise ValueError('标签无效')
                        else: datetime.strptime(value,'%d/%m/%Y %H:%M:%S')
                    except ValueError:
                        issue(line_num,str(pos),'field_type','字段类型或取值无效')
    if count != EXPECTED_COUNTS[ref]:
        issue(0,'*','row_count','实际行数与原件定义不一致')
    return {'success':True,'data':{'file_ref':ref,'format':fmt,'valid':error_count == 0,
            'header':header,'row_count':count,'expected_row_count':EXPECTED_COUNTS[ref],
            'column_count':width,'error_count':error_count,'errors':errors}}

