import pandas as pd

def run(arguments, context):
    root = context.scope_root('business_data').resolve()
    ref = arguments['file_ref']
    path = (root / ref).resolve()
    def fail(code, field, message):
        return {'success':False,'error':{'code':code,'path':field,'message':message,'retryable':False}}
    if not path.is_relative_to(root) or not path.is_file():
        return fail('not_found','file_ref','文件不存在')
    ext = path.suffix.lower()
    if ext not in ('.csv','.data','.parquet','.json'):
        return fail('unsupported_format','file_ref','不支持该文件格式')
    try:
        if ext == '.csv':
            frame = pd.read_csv(path)
        elif ext == '.parquet':
            frame = pd.read_parquet(path)
        elif ext == '.json':
            frame = pd.read_json(path)
        else:
            with path.open(encoding='utf-8') as stream:
                first = stream.readline()
            if '"' in first:
                with path.open(encoding='utf-8') as stream:
                    rows = [shlex.split(line) for line in stream if line.strip()]
                if any(len(row) != len(rows[0]) for row in rows):
                    return fail('invalid_file','file_ref','源文本行宽不一致')
                frame = pd.DataFrame(rows)
            else:
                frame = pd.read_csv(path,sep=r'\s+',header=None)
            frame.columns = ['column_'+str(i+1) for i in range(frame.shape[1])]
        selected = arguments.get('columns',list(frame.columns))
        missing = [name for name in selected if name not in frame.columns]
        if missing:
            return fail('invalid_selection','columns','列不存在：'+str(missing[0]))
        summaries = []
        n = len(frame)
        for name in selected:
            series = frame[name]
            numeric = pd.to_numeric(series,errors='coerce')
            is_numeric = pd.api.types.is_numeric_dtype(series) or (series.notna().sum() and numeric.notna().sum() == series.notna().sum())
            if is_numeric:
                series = numeric.replace([math.inf,-math.inf],math.nan)
            absent = int(series.isna().sum())
            summary = {'column':str(name),'kind':'numeric' if is_numeric else 'categorical',
                       'missing_count':absent,'missing_rate':absent/n if n else 0.0,
                       'numeric':None,'top_values':[]}
            if is_numeric:
                values = series.dropna()
                if not values.empty:
                    summary['numeric'] = {'count':int(values.size),'mean':float(values.mean()),
                      'std':float(values.std(ddof=1)) if len(values)>1 else None,
                      'min':float(values.min()),'q25':float(values.quantile(.25)),
                      'median':float(values.median()),'q75':float(values.quantile(.75)),
                      'max':float(values.max())}
            else:
                counts = series.dropna().astype(str).value_counts().head(arguments.get('top_n',5))
                summary['top_values'] = [{'value':str(value),'count':int(count)} for value,count in counts.items()]
            summaries.append(summary)
        return {'success':True,'data':{'file_ref':ref,'row_count':n,
            'column_count':len(frame.columns),'columns':summaries}}
    except (ValueError, pd.errors.ParserError, OSError) as exc:
        return fail('invalid_file','file_ref',str(exc))

import csv
