from pathlib import Path
import pandas as pd

def run(arguments, context):
    root = context.scope_root('business_data').resolve()
    def fail(code, field, message):
        return {'success':False,'error':{'code':code,'path':field,'message':message,'retryable':False}}
    paths = {key:(root / arguments[key]).resolve() for key in ('observations_file','labels_file','output_file')}
    for key,path in paths.items():
        if not path.is_relative_to(root): return fail('invalid_path',key,'路径超出业务文件范围')
    for key in ('observations_file','labels_file'):
        if not paths[key].is_file(): return fail('not_found',key,'源文件不存在')
    out = paths['output_file']
    if out.exists() or out in (paths['observations_file'],paths['labels_file']):
        return fail('already_exists','output_file','目标文件已存在')
    fmt = out.suffix.lower()
    if fmt not in ('.csv','.parquet'):
        return fail('unsupported_format','output_file','仅支持 CSV 或 Parquet')
    try:
        observations = pd.read_csv(paths['observations_file'],sep=r'\s+',header=None)
        with paths['labels_file'].open(encoding='utf-8') as stream:
            rows = [shlex.split(line) for line in stream if line.strip()]
        if len(rows) != len(observations) or any(len(row)!=2 for row in rows):
            return fail('row_mismatch','labels_file','标签与观测行数或格式不匹配')
        labels = [int(row[0]) for row in rows]
        if any(value not in (-1,1) for value in labels):
            return fail('invalid_file','labels_file','标签须为 -1 或 1')
        observations.columns = ['sensor_'+str(i+1) for i in range(observations.shape[1])]
        table = pd.concat([pd.DataFrame({'observation_index':range(len(rows)),
            'label':labels,'timestamp':[row[1] for row in rows]}),observations],axis=1)
        out.parent.mkdir(parents=True,exist_ok=True)
        if fmt == '.csv': table.to_csv(out,index=False)
        else: table.to_parquet(out,index=False)
        return {'success':True,'data':{'output_file':arguments['output_file'],
            'row_count':len(table),'sensor_count':observations.shape[1],
            'first_label':labels[0],'first_timestamp':rows[0][1],
            'format':fmt[1:]}}
    except (ValueError, OSError, pd.errors.ParserError) as exc:
        return fail('invalid_file','observations_file',str(exc))

