from pathlib import Path
import pandas as pd
from tsfresh.feature_extraction.settings import from_columns

def run(arguments, context):
    def fail(code, path, message):
        return {'success':False,'error':{'code':code,'path':path,'message':message,'retryable':False}}
    root = context.scope_root('business_data').resolve()
    path = (root / arguments['feature_file']).resolve()
    if not path.is_relative_to(root):
        return fail('invalid_path','feature_file','文件路径超出业务文件范围')
    if not path.is_file():
        return fail('not_found','feature_file','特征矩阵文件不存在')
    suffix = path.suffix.lower()
    if suffix not in ('.csv','.parquet'):
        return fail('unsupported_format','feature_file','仅支持 CSV 和 Parquet 特征矩阵')
    try:
        columns = list(pd.read_csv(path, nrows=0).columns) if suffix == '.csv' else list(pd.read_parquet(path).columns)
    except (ValueError, OSError, ImportError) as exc:
        return fail('invalid_file','feature_file',str(exc))
    selected = arguments['feature_columns']
    if len(selected) != len(set(selected)) or any(name not in columns for name in selected):
        return fail('invalid_selection','feature_columns','选定列重复或不在特征矩阵中')
    if any(not name.split('__')[0] or len(name.split('__')) < 2 or not name.split('__')[1] for name in selected):
        return fail('invalid_selection','feature_columns','选定列不符合 tsfresh 特征命名规则')
    try:
        settings = from_columns(selected)
    except (ValueError, TypeError, KeyError, IndexError) as exc:
        return fail('invalid_selection','feature_columns',str(exc))
    return {'success':True,'data':{'feature_file':arguments['feature_file'],
        'selected_columns':selected,'feature_count':len(selected),
        'kind_to_fc_parameters':settings}}

import csv
import math
import shlex
from itertools import zip_longest

KINDS = {
    'st_d1_samples': ('st', 'sample_index'),
    'st_d2_samples': ('st', 'sample_index'),
    'secom_observations': ('secom', 'observation_index'),
    'fdc_monitoring_scores': ('scores', 'score_index'),
    'fdc_alarm_catalog': ('alarms', 'alarm_index'),
}

def run(arguments, context):
    def fail(code, path, message):
        return {'success':False,'error':{'code':code,'path':path,'message':message,'retryable':False}}
    rid = arguments['record_set_id']
    if rid not in KINDS:
        return fail('invalid_record_set','record_set_id','未支持的记录集')
    kind, key = KINDS[rid]
    first = context.records.list(rid,limit=1,order_by=key)
    if not first:
        return fail('empty_record_set','record_set_id','记录集为空，无法定位原始文件')
    root = context.scope_root('business_data').resolve()
    source_names = [first[0]['source_file']]
    if kind == 'secom':
        source_names.append(first[0]['label_file'])
    paths = []
    for name in source_names:
        p = (root / name).resolve()
        if not p.is_relative_to(root) or not p.is_file():
            return fail('source_not_found','record_set_id','记录集引用的原始文件不存在')
        paths.append(p)
    def record_rows():
        offset = 0
        while True:
            batch = context.records.list(rid,limit=5000,offset=offset,order_by=key)
            if not batch:
                break
            yield from batch
            offset += len(batch)
    def parse_bool(value):
        return str(value).strip().lower() in ('1','true')
    def parse_st(row):
        return {'material_id':int(row['MaterialID']),'step_id':int(row['StepID']),
                'duration_ms':float(row['duration_ms']),'feature_1':float(row['feature_1']),
                'is_test':parse_bool(row['is_test']),'target':parse_bool(row['target'])}
    def parse_scores(row):
        return {'t2':float(row['t2']),'spe':float(row['spe']),
                't2_alarm':parse_bool(row['t2_alarm']),'spe_alarm':parse_bool(row['spe_alarm']),
                'any_alarm':parse_bool(row['any_alarm'])}
    def parse_alarms(row):
        return {'wafer_index':int(row['wafer_idx']),'timestamp':row['timestamp'],
                't2':float(row['t2']),'spe':float(row['spe']),
                't2_norm':float(row['t2_norm']),'spe_norm':float(row['spe_norm']),
                'alarm_type':row['alarm_type'],'is_fail':parse_bool(row['is_fail']),
                'top_t2_sensors':row['top_t2_sensors'].split(';'),
                'top_t2_values':[float(v) for v in row['top_t2_values'].split(';')],
                'top_spe_sensors':row['top_spe_sensors'].split(';'),
                'top_spe_values':[float(v) for v in row['top_spe_values'].split(';')],
                'severity':float(row['severity'])}
    def same(a,b):
        if isinstance(a,list) and isinstance(b,list):
            return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
        if isinstance(a,(int,float)) and not isinstance(a,bool) and isinstance(b,(int,float)) and not isinstance(b,bool):
            return math.isclose(a,b,rel_tol=1e-10,abs_tol=1e-10)
        return a==b
    try:
        with paths[0].open(encoding='utf-8',newline='') as stream:
            file_count = sum(1 for _ in stream) - (0 if kind=='secom' else 1)
        sample_indices = sorted(set([0,max(0,file_count//2),max(0,file_count-1)]))
        sampled_values = {}
        mismatches = []
        index_mismatches = field_mismatches = record_count = file_row_count = 0
        records = record_rows()
        def compare_row(i, expected, record):
            nonlocal index_mismatches, field_mismatches
            if record.get('source_file') != source_names[0] or (kind=='secom' and record.get('label_file') != source_names[1]):
                field_mismatches += 1
                if len(mismatches)<20: mismatches.append('row '+str(i)+': source_file/label_file')
            fields = {}
            for field, value in expected.items():
                fields[field] = record.get(field)
                if not same(value,record.get(field)):
                    field_mismatches += 1
                    if len(mismatches)<20: mismatches.append('row '+str(i)+': '+field)
            sampled_values[str(i)] = fields
        with paths[0].open(encoding='utf-8',newline='') as source:
            if kind == 'secom':
                with paths[1].open(encoding='utf-8') as labels:
                    for i, (obs,label) in enumerate(zip_longest(source,labels)):
                        file_row_count += 1
                        rec = next(records,None)
                        if rec is None:
                            index_mismatches += 1
                            if len(mismatches)<20: mismatches.append('row '+str(i)+': missing record')
                            continue
                        record_count += 1
                        if rec[key] != i:
                            index_mismatches += 1
                            if len(mismatches)<20: mismatches.append('row '+str(i)+': '+key+'='+str(rec[key]))
                        if obs is None or label is None:
                            field_mismatches += 1
                            if len(mismatches)<20: mismatches.append('row '+str(i)+': observation/label file lengths differ')
                        elif i in sample_indices:
                            values=obs.split()
                            lab=shlex.split(label)
                            expected={'label':int(lab[0]),'timestamp':lab[1],
                                      'sensor_1':None if values[0].lower()=='nan' else float(values[0]),
                                      'sensor_9':None if values[8].lower()=='nan' else float(values[8]),
                                      'sensor_590':None if values[589].lower()=='nan' else float(values[589])}
                            compare_row(i,expected,rec)
            else:
                reader=csv.DictReader(source)
                parser={'st':parse_st,'scores':parse_scores,'alarms':parse_alarms}[kind]
                for i,row in enumerate(reader):
                    file_row_count += 1
                    rec = next(records,None)
                    if rec is None:
                        index_mismatches += 1
                        if len(mismatches)<20: mismatches.append('row '+str(i)+': missing record')
                        continue
                    record_count += 1
                    if rec[key] != i:
                        index_mismatches += 1
                        if len(mismatches)<20: mismatches.append('row '+str(i)+': '+key+'='+str(rec[key]))
                    if i in sample_indices:
                        compare_row(i,parser(row),rec)
        for rec in records:
            record_count += 1
            index_mismatches += 1
            if len(mismatches)<20: mismatches.append('extra record '+str(rec[key]))
        matching = (file_row_count==record_count and index_mismatches==0 and field_mismatches==0)
        return {'success':True,'data':{'record_set_id':rid,'source_files':source_names,
            'file_row_count':file_row_count,'record_count':record_count,
            'index_mismatch_count':index_mismatches,'field_mismatch_count':field_mismatches,
            'matching':matching,'sampled_indices':sample_indices,
            'sampled_values':sampled_values,'mismatches':mismatches}}
    except (OSError,ValueError,IndexError,KeyError,csv.Error) as exc:
        return fail('invalid_source','record_set_id',str(exc))

