import pandas as pd

def run(arguments, context):
    selected = ['D1', 'D2'] if arguments.get('dataset', 'both') == 'both' else [arguments['dataset']]
    feature = arguments.get('feature', 'feature_1')
    group_by = arguments.get('group_by', ['dataset', 'is_test', 'target'])
    if int(feature.split('_')[1]) > 15 and 'D1' in selected:
        return {'success': False, 'error': {'code': 'unsupported_feature', 'path': 'feature', 'message': 'D1 只包含 feature_1 至 feature_15', 'retryable': False}}
    records = []
    selected_lots = []
    for dataset in selected:
        prefix = 'st_' + dataset.lower()
        if 'material_id' in arguments:
            lot = context.records.get(prefix + '_lots', {'material_id': arguments['material_id']})
            lots = [lot] if lot is not None else []
        else:
            lots = []
            cursor = 0
            while True:
                batch = context.records.list(prefix + '_lots', limit=500, offset=cursor, order_by='material_id')
                if not batch: break
                lots.extend(batch)
                cursor += len(batch)
        lots = [lot for lot in lots if lot is not None and
                ('step_id' not in arguments or arguments['step_id'] in lot['step_ids']) and
                ('is_test' not in arguments or lot['is_test'] == arguments['is_test']) and
                ('target' not in arguments or lot['target'] == arguments['target'])]
        for lot in lots:
            selected_lots.append((dataset, lot['material_id']))
            cursor = 0
            while True:
                batch = context.records.list(prefix + '_samples', filters={'material_id': lot['material_id']}, limit=500, offset=cursor, order_by='sample_index')
                if not batch: break
                for row in batch:
                    if 'step_id' not in arguments or row['step_id'] == arguments['step_id']:
                        records.append({'dataset': dataset, 'material_id': row['material_id'], 'step_id': row['step_id'], 'is_test': row['is_test'], 'target': row['target'], 'duration_ms': row['duration_ms'], 'feature_value': row[feature]})
                cursor += len(batch)
    if not records:
        return {'success': False, 'error': {'code': 'not_found', 'path': 'material_id' if 'material_id' in arguments else 'filters', 'message': '没有符合条件的轨迹', 'retryable': False}}
    frame = pd.DataFrame.from_records(records)
    trajectory_keys = ['dataset', 'material_id', 'step_id', 'is_test', 'target']
    trajectories = frame.groupby(trajectory_keys, dropna=False, sort=True).agg(duration_min=('duration_ms', 'min'), duration_max=('duration_ms', 'max')).reset_index()
    trajectories['duration_span'] = trajectories['duration_max'] - trajectories['duration_min']
    groups = []
    for group_key, samples in frame.groupby(group_by, dropna=False, sort=True):
        values = group_key if isinstance(group_key, tuple) else (group_key,)
        members = trajectories
        for key, value in zip(group_by, values):
            members = members[members[key] == value]
        spans = members['duration_span']
        entry = {key: value.item() if hasattr(value, 'item') else value for key, value in zip(group_by, values)}
        entry.update({'trajectory_count': int(len(members)), 'sample_count': int(len(samples)), 'duration_span_mean': float(spans.mean()), 'duration_span_min': float(spans.min()), 'duration_span_max': float(spans.max()), 'feature_mean': float(samples['feature_value'].mean()), 'feature_std': float(samples['feature_value'].std(ddof=0))})
        groups.append(entry)
    return {'success': True, 'data': {'feature': feature, 'group_by': group_by, 'total_trajectories': int(len(trajectories)), 'total_samples': int(len(frame)), 'groups': groups}}

import pandas as pd

def _all(context, rid, key):
    rows = []
    offset = 0
    while True:
        batch = context.records.list(rid, limit=200, offset=offset, order_by=key)
        if not batch:
            break
        rows.extend(batch)
        offset += len(batch)
    return rows

def _error(code, path, message):
    return {'success': False, 'error': {'code': code, 'path': path, 'message': message, 'retryable': False}}

def _distribution(series):
    values = pd.to_numeric(series, errors='coerce').dropna()
    if values.empty:
        return {'min': None, 'q25': None, 'median': None, 'q75': None, 'max': None, 'mean': None}
    return {'min': float(values.min()), 'q25': float(values.quantile(.25)),
            'median': float(values.median()), 'q75': float(values.quantile(.75)),
            'max': float(values.max()), 'mean': float(values.mean())}

def run(arguments, context):
    sensor = arguments['sensor']
    rows = _all(context, 'secom_observations', 'observation_index')
    if not rows or sensor not in rows[0] or not sensor.startswith('sensor_'):
        return _error('not_found', 'sensor', 'SECOM 传感器不存在')
    frame = pd.DataFrame(rows).sort_values('observation_index')
    values = pd.to_numeric(frame[sensor], errors='coerce')
    dates = pd.to_datetime(frame['timestamp'], format='%d/%m/%Y %H:%M:%S', errors='coerce')
    labels = frame['label'].value_counts()
    source = str(frame.iloc[0]['source_file'])
    label_file = str(frame.iloc[0]['label_file'])
    check = {'checked': False, 'compared_rows': 0, 'sensor_mismatches': 0,
             'label_mismatches': 0, 'timestamp_mismatches': 0}
    if arguments.get('check_source', False):
        root = context.scope_root('business_data')
        matrix_path = (root / source).resolve()
        labels_path = (root / label_file).resolve()
        if root.resolve() not in matrix_path.parents or root.resolve() not in labels_path.parents:
            return _error('invalid_path', 'source_file', '原件路径超出业务文件范围')
        if not matrix_path.is_file():
            return _error('file_missing', 'source_file', 'SECOM 原始观测文件缺失')
        if not labels_path.is_file():
            return _error('file_missing', 'label_file', 'SECOM 标签文件缺失')
        column = int(sensor.split('_')[1]) - 1
        raw = pd.read_csv(matrix_path, sep=r'\s+', header=None, usecols=[column]).iloc[:, 0]
        original_labels = pd.read_csv(labels_path, sep=' ', header=None,
                                      names=['label', 'timestamp'], skipinitialspace=True, quotechar='"')
        if len(raw) != len(frame) or len(original_labels) != len(frame):
            return _error('source_mismatch', 'source_file', '原件与记录的观测行数不同')
        raw_values = pd.to_numeric(raw, errors='coerce').reset_index(drop=True)
        stored_values = values.reset_index(drop=True)
        equal = raw_values.eq(stored_values) | (raw_values.isna() & stored_values.isna())
        check = {'checked': True, 'compared_rows': len(frame),
                 'sensor_mismatches': int((~equal).sum()),
                 'label_mismatches': int((original_labels['label'].to_numpy() != frame['label'].to_numpy()).sum()),
                 'timestamp_mismatches': int((original_labels['timestamp'].to_numpy() != frame['timestamp'].to_numpy()).sum())}
    data = {'sensor': sensor, 'observation_count': len(frame),
            'valid_count': int(values.count()), 'missing_count': int(values.isna().sum()),
            'missing_rate': float(values.isna().mean()), 'distribution': _distribution(values),
            'label_counts': {'pass': int(labels.get(-1, 0)), 'fail': int(labels.get(1, 0))},
            'first_timestamp': dates.min().isoformat(sep=' ') if dates.notna().any() else None,
            'last_timestamp': dates.max().isoformat(sep=' ') if dates.notna().any() else None,
            'timestamp_count': int(dates.count()), 'source_file': source,
            'label_file': label_file, 'source_check': check}
    return {'success': True, 'data': data}

