def run(arguments, context):
    score_index = arguments.get('score_index')
    if score_index is not None:
        one = context.records.get('fdc_monitoring_scores', {'score_index': score_index})
        if one is None:
            return _error('not_found', 'score_index', '评分不存在')
        rows = [one]
    else:
        rows = _all(context, 'fdc_monitoring_scores', 'score_index')
    frame = pd.DataFrame(rows)
    total_count = len(frame)
    for field in ('t2', 'spe'):
        if 'min_' + field in arguments:
            frame = frame.loc[frame[field] >= arguments['min_' + field]]
        if 'max_' + field in arguments:
            frame = frame.loc[frame[field] <= arguments['max_' + field]]
    for field in ('t2_alarm', 'spe_alarm', 'any_alarm'):
        if field in arguments:
            frame = frame.loc[frame[field] == arguments[field]]
    n = len(frame)
    counts = {'none': 0, 't2_only': 0, 'spe_only': 0, 'both': 0}
    if n:
        grouped = frame.groupby(['t2_alarm', 'spe_alarm']).size()
        counts = {'none': int(grouped.get((False, False), 0)),
                  't2_only': int(grouped.get((True, False), 0)),
                  'spe_only': int(grouped.get((False, True), 0)),
                  'both': int(grouped.get((True, True), 0))}
    alarms = int(frame['any_alarm'].sum()) if n else 0
    return {'success': True, 'data': {
        'total_count': total_count, 'selected_count': n, 'any_alarm_count': alarms,
        'alarm_rate': alarms / n if n else 0.0,
        't2_alarm_count': int(frame['t2_alarm'].sum()) if n else 0,
        'spe_alarm_count': int(frame['spe_alarm'].sum()) if n else 0,
        'alarm_combinations': counts,
        't2_distribution': _distribution(frame['t2']),
        'spe_distribution': _distribution(frame['spe'])}}

import pandas as pd

def _all(context, rid, key):
    rows = []
    offset = 0
    while True:
        batch = context.records.list(rid, limit=200, offset=offset, order_by=key)
        if not batch:
            break
        rows.extend(batch)
        offset += len(batch)
    return rows

def _error(code, path, message):
    return {'success': False, 'error': {'code': code, 'path': path, 'message': message, 'retryable': False}}

def _distribution(series):
    values = pd.to_numeric(series, errors='coerce').dropna()
    if values.empty:
        return {'min': None, 'q25': None, 'median': None, 'q75': None, 'max': None, 'mean': None}
    return {'min': float(values.min()), 'q25': float(values.quantile(.25)),
            'median': float(values.median()), 'q75': float(values.quantile(.75)),
            'max': float(values.max()), 'mean': float(values.mean())}

def _contributors(frame, sensors_column, values_column):
    pairs = []
    for row in frame.itertuples(index=False):
        for sensor, value in zip(getattr(row, sensors_column), getattr(row, values_column)):
            pairs.append({'sensor': sensor, 'contribution': float(value)})
    if not pairs:
        return []
    summary = (pd.DataFrame(pairs).groupby('sensor', as_index=False)
               .agg(frequency=('sensor', 'size'), total_contribution=('contribution', 'sum'))
               .sort_values(['frequency', 'total_contribution', 'sensor'],
                            ascending=[False, False, True]))
    return [{'sensor': str(row.sensor), 'frequency': int(row.frequency),
             'total_contribution': float(row.total_contribution)}
            for row in summary.head(10).itertuples(index=False)]

def run(arguments, context):
    alarm_index = arguments.get('alarm_index')
    if alarm_index is not None:
        one = context.records.get('fdc_alarm_catalog', {'alarm_index': alarm_index})
        if one is None:
            return _error('not_found', 'alarm_index', '告警不存在')
        rows = [one]
    else:
        rows = _all(context, 'fdc_alarm_catalog', 'alarm_index')
    frame = pd.DataFrame(rows)
    if 'alarm_type' in arguments:
        frame = frame.loc[frame['alarm_type'] == arguments['alarm_type']]
    if 'is_fail' in arguments:
        frame = frame.loc[frame['is_fail'] == arguments['is_fail']]
    if 'min_severity' in arguments:
        frame = frame.loc[frame['severity'] >= arguments['min_severity']]
    if frame.empty:
        return {'success': True, 'data': {'alarm_count': 0,
            'category_counts': {'t2_only': 0, 'spe_only': 0, 'both': 0},
            'label_counts': {'pass': 0, 'fail': 0},
            'severity_distribution': _distribution(pd.Series(dtype=float)),
            'top_t2_contributors': [], 'top_spe_contributors': [],
            'score_match_count': 0, 'score_alarm_consistent_count': 0,
            'score_t2_distribution': _distribution(pd.Series(dtype=float)),
            'score_spe_distribution': _distribution(pd.Series(dtype=float)),
            'severity_ranking': []}}
    categories = frame['alarm_type'].value_counts()
    labels = frame['is_fail'].value_counts()
    scores = _all(context, 'fdc_monitoring_scores', 'score_index')
    score_map = {r['score_index']: r for r in scores}
    matched = [score_map[int(i)] for i in frame['wafer_index'] if int(i) in score_map]
    consistent = sum(bool(x['any_alarm']) for x in matched)
    ranked = frame.sort_values(['severity', 'alarm_index'], ascending=[False, True])
    return {'success': True, 'data': {
        'alarm_count': len(frame),
        'category_counts': {'t2_only': int(categories.get('T2-only', 0)),
                            'spe_only': int(categories.get('SPE-only', 0)),
                            'both': int(categories.get('both', 0))},
        'label_counts': {'pass': int(labels.get(False, 0)),
                         'fail': int(labels.get(True, 0))},
        'severity_distribution': _distribution(frame['severity']),
        'top_t2_contributors': _contributors(frame, 'top_t2_sensors', 'top_t2_values'),
        'top_spe_contributors': _contributors(frame, 'top_spe_sensors', 'top_spe_values'),
        'score_match_count': len(matched),
        'score_alarm_consistent_count': consistent,
        'score_t2_distribution': _distribution(pd.Series([x['t2'] for x in matched], dtype=float)),
        'score_spe_distribution': _distribution(pd.Series([x['spe'] for x in matched], dtype=float)),
        'severity_ranking': [int(x) for x in ranked['alarm_index'].head(10)]}}

import pandas as pd

def _all(context, rid, key):
    rows = []
    offset = 0
    while True:
        batch = context.records.list(rid, limit=200, offset=offset, order_by=key)
        if not batch:
            break
        rows.extend(batch)
        offset += len(batch)
    return rows

def _error(code, path, message):
    return {'success': False, 'error': {'code': code, 'path': path, 'message': message, 'retryable': False}}

def _distribution(series):
    values = pd.to_numeric(series, errors='coerce').dropna()
    if values.empty:
        return {'min': None, 'q25': None, 'median': None, 'q75': None, 'max': None, 'mean': None}
    return {'min': float(values.min()), 'q25': float(values.quantile(.25)),
            'median': float(values.median()), 'q75': float(values.quantile(.75)),
            'max': float(values.max()), 'mean': float(values.mean())}

def _rate(numerator, denominator):
    return float(numerator / denominator) if denominator else 0.0

def run(arguments, context):
    method_name = arguments.get('method_name')
    if method_name is not None:
        one = context.records.get('fdc_method_comparison', {'method_name': method_name})
        if one is None:
            return _error('not_found', 'method_name', '方法不存在')
        rows = [one]
    else:
        rows = _all(context, 'fdc_method_comparison', 'method_name')
    frame = pd.DataFrame(rows)
    metric = arguments.get('sort_by', 'f1')
    ascending = arguments.get('ascending', metric == 'fpr')
    frame = frame.sort_values([metric, 'method_name'], ascending=[ascending, True])
    methods = []
    for row in frame.to_dict('records'):
        tp, fp, fn, tn = (float(row[k]) for k in ('tp','fp','fn','tn'))
        precision = _rate(tp, tp + fp)
        recall = _rate(tp, tp + fn)
        recalculated = {'tpr': recall, 'fpr': _rate(fp, fp + tn),
                        'precision': precision,
                        'f1': _rate(2 * precision * recall, precision + recall)}
        methods.append({k: row[k] for k in ('method_name','k','var_explained',
                       't2_limit','spe_limit','tp','fp','fn','tn','tpr','fpr','precision','f1')}
                       | {'recomputed': recalculated})
    ranking = [x['method_name'] for x in methods]
    return {'success': True, 'data': {'method_count': len(methods),
        'ranked_by': metric, 'ascending': ascending,
        'ranking': ranking, 'methods': methods,
        'metric_gap': float(frame[metric].max() - frame[metric].min())}}

