def run(arguments, context):
    sensor = arguments.get('sensor')
    if sensor is not None:
        one = context.records.get('spc_sensor_summary', {'sensor': sensor})
        if one is None:
            return _error('not_found', 'sensor', 'SPC 传感器不存在')
        rows = [one]
    else:
        rows = _all(context, 'spc_sensor_summary', 'sensor')
    frame = pd.DataFrame(rows)
    for i in range(1, 9):
        frame['rule_' + str(i)] = frame['rule_' + str(i)].astype(int)
    frame['mean_delta'] = frame['mu_monitoring'] - frame['mu']
    frame['cpk_change'] = frame['cpk_monitoring'] - frame['cpk_baseline']
    frame['rule_total'] = frame[['rule_' + str(i) for i in range(1, 9)]].sum(axis=1)
    sort_by = arguments.get('sort_by', 'drift_ratio')
    ascending = arguments.get('ascending', False)
    ranked = frame.sort_values([sort_by, 'sensor'], ascending=[ascending, True])
    details = []
    for r in ranked.to_dict('records'):
        details.append({k: r[k] for k in ('sensor','mu','mu_monitoring','mean_delta',
                        'mean_shift_sigma','sigma_within','sigma_overall','drift_ratio',
                        'cp','cpk_baseline','cpk_monitoring','cpk_change','flag_rate',
                        'flagged_points','n_monitoring','rule_total',
                        'rule_1','rule_2','rule_3','rule_4','rule_5','rule_6','rule_7','rule_8')})
    total_monitoring = int(frame['n_monitoring'].sum())
    total_flagged = int(frame['flagged_points'].sum())
    return {'success': True, 'data': {
        'sensor_count': len(frame), 'ranked_by': sort_by, 'ascending': ascending,
        'ranking': [r['sensor'] for r in details], 'sensors': details,
        'mean_baseline': float(frame['mu'].mean()),
        'mean_monitoring': float(frame['mu_monitoring'].mean()),
        'mean_drift_ratio': float(frame['drift_ratio'].mean()),
        'mean_flag_rate': float(frame['flag_rate'].mean()),
        'mean_cpk_change': float(frame['cpk_change'].mean()),
        'total_flagged': total_flagged, 'total_monitoring': total_monitoring,
        'pooled_flag_rate': total_flagged / total_monitoring if total_monitoring else 0.0,
        'rule_totals': {'rule_' + str(i): int(frame['rule_' + str(i)].sum())
                        for i in range(1, 9)}}}

def run(arguments, context):
    left_id, right_id = 'fdc_alarm_catalog', 'fdc_monitoring_scores'
    left_key, right_key, match_field = 'alarm_index', 'score_index', 'wafer_index'
    use_left = left_key in arguments
    use_right = 'wafer_index' in arguments
    if use_left == use_right:
        return {'success': False, 'error': {'code':'invalid_selection','path':'arguments','message':'恰好指定一个查询键','retryable':False}}
    if use_left:
        left_rows = [context.records.get(left_id, {left_key: arguments[left_key]})]
        if left_rows[0] is None:
            return {'success':False,'error':{'code':'not_found','path':left_key,'message':'采样或告警不存在','retryable':False}}
        right_row = context.records.get(right_id, {right_key: left_rows[0][match_field]})
        rows = [{'left':left_rows[0],'right':right_row}]
        total = 1
    else:
        right_row = context.records.get(right_id, {right_key: arguments['wafer_index']})
        left_rows = []
        offset = 0
        while True:
            batch = context.records.list(left_id, filters={match_field:arguments['wafer_index']}, limit=500, offset=offset, order_by=left_key)
            if not batch: break
            left_rows.extend(batch)
            offset += len(batch)
        if right_row is None and not left_rows:
            return {'success':False,'error':{'code':'not_found','path':'wafer_index','message':'关联对象不存在','retryable':False}}
        rows = [{'left':row,'right':right_row} for row in left_rows]
        total = len(rows)
    missing_right = sorted({row['left'][match_field] for row in rows if row['right'] is None})
    missing_left = [arguments['wafer_index']] if use_right and right_row is not None and not rows else []
    return {'success':True,'data':{'rows':rows,'right_record':right_row,'total':total,
        'missing_right_keys':missing_right,'missing_left_keys':missing_left}}
